 export const AGENT_FIX = "agent-fix";
+// The trust rule is fixed, not configurable: only these two roles may vouch for a label.
+export const TRUSTED_PERMISSIONS = ["admin", "maintain"] as const;
+// A collaborator's role is re-read at most this often, so a demoted admin stops being trusted within a minute.
+const PERMISSION_TTL_MS = 60_000;
 const PAGE_CAP = 10;

 export interface LabelEvent {
@@ -48,6 +52,7 @@ const labelNames = (i: GhIssue) => (i.labels ?? []).map((l) => (typeof l === "string" ? l : l.name));

 export class Maintainer {
   private identity?: { id: number; slug: string };
+  private roles = new Map<string, { role: string | null; at: number }>();

   constructor(
     private readonly app: Projects,
@@ -74,6 +79,36 @@ export class Maintainer {
     return this.identity;
   }

+  /**
+   * A collaborator's role on the repo, or null when they aren't one, re-read after PERMISSION_TTL_MS. The route is
+   * documented under Metadata read, which the App already holds. A 404 means not a collaborator (untrusted); any other
+   * failure throws, so the caller fails closed.
+   */
+  private async role(owner: string, repo: string, login: string): Promise<string | null> {
+    const key = `${owner.toLowerCase()}/${repo.toLowerCase()} ${login.toLowerCase()}`;
+    const hit = this.roles.get(key);
+    if (hit && Date.now() - hit.at < PERMISSION_TTL_MS) return hit.role;
+    const r = await this.app.appCall(owner, repo, { metadata: "read" }, "GET", `/repos/${owner}/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
+    if (r.status !== 200 && r.status !== 404) throw new Error(`couldn't read ${login}'s role on ${owner}/${repo} (GitHub said ${r.status})`);
+    const role = r.status === 200 ? String(r.body.role_name ?? r.body.permission ?? "") || null : null;
+    this.roles.set(key, { role, at: Date.now() });
+    return role;
+  }
+
+  /** Whether this label event was made by our App or by a collaborator with admin or maintain. */
+  private async trustedEvent(e: GhTimelineEvent, owner: string, repo: string): Promise<boolean> {
+    const id = await this.appIdentity();
+    const via = e.performed_via_github_app;
+    if (via?.id != null && Number(via.id) === id.id) return true;
+    const login = e.actor?.login;
+    if (!login) return false;
+    if (id.slug && login.toLowerCase() === `${id.slug.toLowerCase()}[bot]`) return true;
+    const role = await this.role(owner, repo, login);
+    return role !== null && (TRUSTED_PERMISSIONS as readonly string[]).includes(role);
+  }
+
   /** One issue's timeline reduced to label events (optionally one label), each with its trust verdict. */
   async labelEvents(repo: string | undefined, number: number, only?: string): Promise<{ repo: string; number: number; events: LabelEvent[] }> {
     const [owner, name] = this.target(repo);
@@ -97,7 +132,7 @@ export class Maintainer {
