diff --git a/github/connections/github-mcp/test/maintainer.test.ts b/github/connections/github-mcp/test/maintainer.test.ts
index 2b7e0c1..e41a9d5 100644
--- a/github/connections/github-mcp/test/maintainer.test.ts
+++ b/github/connections/github-mcp/test/maintainer.test.ts
@@ -40,3 +40,38 @@ test("a label event lists its actor and app", async () => {
   assert.equal(events[0].actor, "alice");
 });
+
+test("a label is trusted only from our App or an admin or maintain collaborator", async () => {
+  const roles: Record<string, string> = { alice: "admin", bob: "maintain", carol: "write", dave: "triage", erin: "read" };
+  const gh = fakeApp({
+    timeline: ["alice", "bob", "carol", "dave", "erin", "mallory", "acme-agents[bot]"].map((login) => labeled(login)),
+    permission: (login) => (roles[login] ? { status: 200, body: { role_name: roles[login] } } : { status: 404, body: {} }),
+  });
+  const { events } = await new Maintainer(gh, "acme/aidenhq").labelEvents(undefined, 7);
+  assert.deepEqual(events.map((e) => [e.actor, e.trusted]), [["alice", true], ["bob", true], ["carol", false], ["dave", false], ["erin", false], ["mallory", false], ["acme-agents[bot]", true]]);
+  assert.ok(gh.calls.filter((c) => c.path.includes("/permission")).every((c) => c.perms.metadata === "read" && Object.keys(c.perms).length === 1));
+});
+
+test("a role read that fails with anything but 404 fails closed", async () => {
+  const gh = fakeApp({ timeline: [labeled("alice")], permission: () => ({ status: 500, body: {} }) });
+  await assert.rejects(new Maintainer(gh, "acme/aidenhq").labelEvents(undefined, 7), /couldn't read alice's role/);
+});
+
+test("a role is re-read after a minute, once inside the window", async (t) => {
+  t.mock.timers.enable({ apis: ["Date"] });
+  let role = "admin";
+  const gh = fakeApp({ timeline: [labeled("alice"), labeled("alice")], permission: () => ({ status: 200, body: { role_name: role } }) });
+  const m = new Maintainer(gh, "acme/aidenhq");
+  assert.deepEqual((await m.labelEvents(undefined, 7)).events.map((e) => e.trusted), [true, true]);
+  role = "write";
+  t.mock.timers.tick(61_000);
+  assert.deepEqual((await m.labelEvents(undefined, 7)).events.map((e) => e.trusted), [false, false]);
+  assert.equal(gh.calls.filter((c) => c.path.includes("/permission")).length, 2);
+});
